import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] a = new int[n];
        String[] aStr = br.readLine().trim().split(" ");
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aStr[i]);
        }
        int[] b = new int[n];
        String[] bStr = br.readLine().trim().split(" ");
        for (int i = 0; i < n; i++) {
            b[i] = Integer.parseInt(bStr[i]);
        }

        // 辅助数组，记录 B 的数值和原始下标
        int[][] aux = new int[n][2];
        for (int i = 0; i < n; i++) {
            aux[i][0] = b[i];
            aux[i][1] = i;
        }

        // 按数值排序
        Arrays.sort(aux, Comparator.comparingInt(o -> o[0]));
        Arrays.sort(a);

        // 将排序后的 A 填入对应位置
        for (int i = 0; i < n; i++) {
            aux[i][0] = a[i];
        }

        // 按原始下标排序，恢复 B 的原始顺序
        Arrays.sort(aux, Comparator.comparingInt(o -> o[1]));

        // 输出结果
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(aux[i][0]);
            if (i < n - 1) sb.append(" ");
        }
