### C++

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    // 辅助数组，记录 B 的数值和原始下标
    vector<pair<int, int>> aux(n);
    for (int i = 0; i < n; ++i) {
        aux[i] = {b[i], i};
    }

    // 按数值排序
    sort(aux.begin(), aux.end(), 
         [](const pair<int, int>& x, const pair<int, int>& y) {
             return x.first < y.first;
         });

    sort(a.begin(), a.end());

    // 将排序后的 A 填入对应位置
    for (int i = 0; i < n; ++i) {
        aux[i].first = a[i];
    }

    // 按原始下标排序，恢复 B 的原始顺序
    sort(aux.begin(), aux.end(), 
         [](const pair<int, int>& x, const pair<int, int>& y) {
             return x.second < y.second;
         });

    // 输出结果
    for (int i = 0; i < n; ++i) {
        cout << aux[i].first;
        if (i < n - 1) cout << " ";
    }
    cout << endl;

    return 0;
}
```
